private const val WAITLISTS_COLLECTION = "waitlists"
private const val MAX_STORED_IMAGE_BYTES = 700_000
private const val MAX_IMAGE_DIMENSION = 1024

private fun decodeCampsiteImageBitmap(raw: String?): ImageBitmap? {
    if (raw.isNullOrBlank()) return null
    val clean = raw.substringAfter("base64,", raw).trim()
    if (clean.length < 32 || clean.startsWith("http://") || clean.startsWith("https://")) {
        return null
    }
    return runCatching {
        val bytes = Base64.decode(clean, Base64.DEFAULT)
        BitmapFactory.decodeByteArray(bytes, 0, bytes.size)?.asImageBitmap()
    }.getOrNull()
}

private suspend fun encodeUriToCompressedBase64(
    context: android.content.Context,
    uri: Uri,
): String? = withContext(Dispatchers.IO) {
    runCatching {
        val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }
        context.contentResolver.openInputStream(uri)?.use { stream ->
            BitmapFactory.decodeStream(stream, null, bounds)
        }
        val longestSide = max(bounds.outWidth, bounds.outHeight)
        var sampleSize = 1
        while (longestSide / sampleSize > MAX_IMAGE_DIMENSION) {
            sampleSize *= 2
        }

        val decodeOpts = BitmapFactory.Options().apply { inSampleSize = sampleSize }
        val decoded = context.contentResolver.openInputStream(uri)?.use { stream ->
            BitmapFactory.decodeStream(stream, null, decodeOpts)
        } ?: return@withContext null

        val out = ByteArrayOutputStream()
        var quality = 85
        decoded.compress(Bitmap.CompressFormat.JPEG, quality, out)
        while (out.size() > MAX_STORED_IMAGE_BYTES && quality > 25) {
            out.reset()
            quality -= 15
            decoded.compress(Bitmap.CompressFormat.JPEG, quality, out)
        }
        decoded.recycle()

        if (out.size() > MAX_STORED_IMAGE_BYTES) return@withContext null
        Base64.encodeToString(out.toByteArray(), Base64.NO_WRAP)
    }.getOrNull()
}

/**
 * Documentation generated by Gemini
 * Displays detailed information and action controls for a specific campsite.
 *
 * @param navController Navigation controller for routing back or navigating to edit forms.
 * @param campsiteId Firestore document ID of the campsite to display.
 * @param deviceId the current user's device ID.
 * @param ratingRepository where ratings are stored.
 */
@Composable
fun CampsiteInfoScreen(
    navController: NavController,
    campsiteId: String,
    deviceId: String,
    ratingRepository: RatingRepository = remember { FirestoreRatingRepository() },
) {
    val context = LocalContext.current
    val coroutineScope = rememberCoroutineScope()

    var campsite by remember { mutableStateOf<Campsite?>(null) }
    var currentUser by remember { mutableStateOf<User?>(null) }
    var isLoading by remember { mutableStateOf(true) }

    var openWaitlists by remember { mutableStateOf<List<Waitlist>>(emptyList()) }
    var waitlistsError by remember { mutableStateOf<String?>(null) }
    val lotteryJoinRepository = remember { FirestoreLotteryJoinRepository() }

    var isUploadingImage by remember { mutableStateOf(false) }
    var imageUploadMessage by remember { mutableStateOf<String?>(null) }
    var imageUploadError by remember { mutableStateOf<String?>(null) }

    var myRating by remember { mutableStateOf<Int?>(null) }
    var showRateDialog by remember { mutableStateOf(false) }
    var showQrDialog by remember { mutableStateOf(false) }
    var isSubmittingRating by remember { mutableStateOf(false) }
    var ratingMessage by remember { mutableStateOf<String?>(null) }
    var ratingError by remember { mutableStateOf<String?>(null) }
    var showMessageOwnerDialog by remember { mutableStateOf(false) }
    var messageSentNotice by remember { mutableStateOf<String?>(null) }
    val messageRepository = remember { FirestoreMessageRepository() }

    val imagePickerLauncher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.PickVisualMedia(),
    ) { uri ->
        if (uri == null) return@rememberLauncherForActivityResult
        isUploadingImage = true
        imageUploadError = null
        imageUploadMessage = null
        coroutineScope.launch {
            val encoded = encodeUriToCompressedBase64(context, uri)
            if (encoded == null) {
                isUploadingImage = false
                imageUploadError = "Could not process image (must be under ~700 KB after compression)."
                return@launch
            }
            FirebaseFirestore.getInstance()
                .collection("campsites")
                .document(campsiteId)
                .update("imageUrl", encoded)
                .addOnSuccessListener {
                    isUploadingImage = false
                    campsite = campsite?.copy(imageUrl = encoded)
                    imageUploadMessage = "Campsite image uploaded."
                }
                .addOnFailureListener { err ->
                    isUploadingImage = false
                    imageUploadError = err.message ?: "Failed to upload image."
                }
        }
    }

    LaunchedEffect(campsiteId, deviceId) {
        ratingRepository.getMyRating(
            campsiteId,
            deviceId,
            onSuccess = { myRating = it },
            onFailure = { Log.e("Rating", "Could not load your rating", it) },
        )
    }

    fun submitRating(stars: Int) {
        if (isSubmittingRating) return
        isSubmittingRating = true
        ratingError = null
        ratingMessage = null
        ratingRepository.submitRating(
            campsiteId,
            deviceId,
            stars,
            onSuccess = { totals ->
                isSubmittingRating = false
                myRating = stars
                campsite = campsite?.copy(
                    rating = totals.average,
                    ratingSum = totals.sum,
                    ratingCount = totals.count,
                )
                ratingMessage = "Thanks! You rated this campsite $stars of ${RatingPolicy.MAX_STARS} stars."
            },
            onFailure = {
                isSubmittingRating = false
                ratingError = it.message ?: "Could not save your rating"
            },
        )
    }

    LaunchedEffect(campsiteId) {
        val db = FirebaseFirestore.getInstance()
        db.collection("campsites").document(campsiteId).get()
            .addOnSuccessListener { doc ->
                campsite = doc.toObject(Campsite::class.java)?.copy(campsiteId = doc.id)
                db.collection("users").document(deviceId).get()
                    .addOnSuccessListener { userDoc ->
                        currentUser = userDoc.toObject(User::class.java)
                        isLoading = false
                    }
                    .addOnFailureListener { isLoading = false }
            }
            .addOnFailureListener { isLoading = false }
    }

    // Live waitlists that include this campsite (US 01.02.01 join target).
    DisposableEffect(campsiteId) {
        val listener = FirebaseFirestore.getInstance()
            .collection(WAITLISTS_COLLECTION)
            .whereArrayContains("campsiteIds", campsiteId)
            .addSnapshotListener { snapshot, error ->
                if (error != null) {
                    waitlistsError = error.message
                    return@addSnapshotListener
                }
                waitlistsError = null
                // bookingWaitlist() reads both spellings of the drawn flag in stored lotteries.
                openWaitlists = snapshot?.documents?.mapNotNull { doc ->
                    runCatching { doc.bookingWaitlist() }.getOrNull()
                }.orEmpty()
            }
        onDispose { listener.remove() }
    }

    var reservedDates by remember { mutableStateOf<List<Date>>(emptyList()) }
    var hasError by remember { mutableStateOf(false) }

    DisposableEffect(campsiteId) {
        isLoading = true
        hasError = false

        val listener = FirebaseFirestore.getInstance()
            .collection("reservations")
            .whereEqualTo("campsiteId", campsiteId)
            .whereIn(
                "status",
                listOf(ReservationStatus.PENDING.name, ReservationStatus.CONFIRMED.name)
            )
            .addSnapshotListener { snapshot, error ->
                if (error != null || snapshot == null) {
                    Log.e("ReservedDates", "Failed to load", error)
                    hasError = true
                    isLoading = false
                    return@addSnapshotListener
                }

                val dates = snapshot.documents
                    .flatMap { doc ->
                        (doc.get("reservedDates") as? List<*>)
                            ?.mapNotNull { (it as? Timestamp)?.toDate() }
                            ?: emptyList()
                    }
                    .distinct()
                    .sorted()

                reservedDates = dates
                isLoading = false
            }

        onDispose { listener.remove() }
    }

    val isOwnerOfSite = campsite != null && campsite!!.ownerId == deviceId
    val isAdmin = currentUser?.isAdmin == true
    val canEdit = isOwnerOfSite
    val canDelete = isOwnerOfSite || isAdmin
    val canRate = campsite != null && RatingPolicy.canRate(campsite!!.ownerId, deviceId)

    if (showQrDialog && campsite != null) {
        CampsiteQrDialog(
            campsiteId = campsiteId,
            campsiteName = campsite!!.name,
            onDismiss = { showQrDialog = false },
        )
    }

    if (showRateDialog) {
        RateCampsiteDialog(
            initialStars = myRating,
            onSubmit = { stars ->
                showRateDialog = false
                submitRating(stars)
            },
            onDismiss = { showRateDialog = false },
        )
    }

    if (showMessageOwnerDialog && campsite != null) {
        SendMessageDialog(
            title = "Message owner",
            fromUserId = deviceId,
            toUserId = campsite!!.ownerId,
            campsiteId = campsiteId,
            messageRepository = messageRepository,
            onSent = { messageSentNotice = "Message sent to the campsite owner." },
            onDismiss = { showMessageOwnerDialog = false },
        )
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .statusBarsPadding()
            .padding(16.dp),
    ) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.Absolute.Left,
        ) {
            Button(
                onClick = { navController.popBackStack() },
                shape = RectangleShape,
                modifier = Modifier.testTag("toBackButton"),
            ) {
                Text("Back")
            }
        }

        Spacer(modifier = Modifier.height(16.dp))

        when {
            isLoading -> {
                Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                    CircularProgressIndicator()
                }
            }
            campsite == null -> {
                Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                    Text("Campsite details not found.", fontSize = 20.sp)
                }
            }
            else -> {
                val imageUrl = campsite!!.imageUrl
                val decodedBitmap = remember(imageUrl) { decodeCampsiteImageBitmap(imageUrl) }

                if (!imageUrl.isNullOrBlank()) {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(190.dp)
                            .background(Color(0xFFF5F5F5), RoundedCornerShape(8.dp))
                            .border(1.dp, Color.LightGray, RoundedCornerShape(8.dp))
                            .testTag("campsiteImageContainer"),
                        contentAlignment = Alignment.Center,
                    ) {
                        if (decodedBitmap != null) {
                            Image(
                                bitmap = decodedBitmap,
                                contentDescription = "Photo of ${campsite!!.name}",
                                contentScale = ContentScale.Crop,
                                modifier = Modifier
                                    .fillMaxSize()
                                    .testTag("campsiteImage"),
                            )
                        } else {
                            Text(
                                text = "Image stored: $imageUrl",
                                fontSize = 13.sp,
                                modifier = Modifier
                                    .padding(12.dp)
                                    .testTag("campsiteImageFallback"),
                            )
                        }
                    }
                    Spacer(modifier = Modifier.height(12.dp))
                }

                Text(text = campsite!!.name, fontSize = 40.sp)
                Spacer(modifier = Modifier.height(8.dp))
                Text(text = "Location: ${campsite!!.address}", fontSize = 18.sp)
                Text(
                    text = "Max Occupancy: ${campsite!!.maxOccupancy} | Price: $${campsite!!.pricePerNight}/night",
                    fontSize = 16.sp,
                )
                Text(
                    text = "Rating: ${RatingPolicy.summary(RatingPolicy.totalsOf(campsite!!))}",
                    fontSize = 16.sp,
                    modifier = Modifier.testTag("campsiteRatingText"),
                )
                Spacer(modifier = Modifier.height(16.dp))
                Text(text = campsite!!.description, fontSize = 18.sp)
                if (campsite!!.rules.isNotBlank()) {
                    Spacer(modifier = Modifier.height(8.dp))
                    Text(text = "Rules: ${campsite!!.rules}", fontSize = 14.sp)
                }
            }
        }

        Spacer(modifier = Modifier.weight(1f))

        Column(modifier = Modifier.fillMaxWidth()) {
            imageUploadError?.let {
                Text(it, color = MaterialTheme.colorScheme.error, fontSize = 14.sp, modifier = Modifier.testTag("imageUploadErrorText"))
                Spacer(modifier = Modifier.height(4.dp))
            }
            imageUploadMessage?.let {
                Text(it, fontSize = 14.sp, modifier = Modifier.testTag("imageUploadMessageText"))
                Spacer(modifier = Modifier.height(4.dp))
            }
            ratingError?.let {
                Text(it, color = MaterialTheme.colorScheme.error, fontSize = 14.sp)
                Spacer(modifier = Modifier.height(4.dp))
            }
            ratingMessage?.let {
                Text(it, fontSize = 14.sp, modifier = Modifier.testTag("ratingMessageText"))
                Spacer(modifier = Modifier.height(4.dp))
            }
            messageSentNotice?.let {
                Text(it, fontSize = 14.sp, modifier = Modifier.testTag("messageSentText"))
                Spacer(modifier = Modifier.height(4.dp))
            }

            if (isOwnerOfSite) {
                Column(
                    modifier = Modifier.weight(1f)   // takes the remaining space
                ) {
                    if (!reservedDates.isEmpty()) {

                        Text("Reserved Dates", fontSize = 24.sp)

                        LazyColumn(
                            modifier = Modifier
                                .padding(5.dp)
                                .fillMaxSize(),
                            verticalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            items(reservedDates) { date ->
                                Card(modifier = Modifier.fillMaxWidth()) {
                                    Row(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .padding(horizontal = 16.dp, vertical = 12.dp)
                                    ) { Text(date.toString(), fontSize = 20.sp) }
                                }
                            }
                        }
                    }
                    else {

                        Text("No Dates Reserved", fontSize = 24.sp)

                    }
                }
            }

            if (canEdit) {
                Button(
                    onClick = { navController.navigate("registerCampsite/$campsiteId") },
                    shape = RectangleShape,
                    modifier = Modifier.fillMaxWidth(),
                ) {
                    Text("Edit Campsite Details")
                }
                Spacer(modifier = Modifier.height(8.dp))
                Button(
                    onClick = {
                        imagePickerLauncher.launch(
                            PickVisualMediaRequest(ActivityResultContracts.PickVisualMedia.ImageOnly)
                        )
                    },
                    enabled = !isUploadingImage,
                    shape = RectangleShape,
                    modifier = Modifier
                        .fillMaxWidth()
                        .testTag("uploadImageButton"),
                ) {
                    Text(if (isUploadingImage) "Uploading Image..." else "Upload Image")
                }
                Spacer(modifier = Modifier.height(8.dp))
                Button(
                    onClick = { showQrDialog = true },
                    shape = RectangleShape,
                    modifier = Modifier.fillMaxWidth().testTag("showQrCodeButton"),
                ) {
                    Text("Show QR Code")
                }
                Spacer(modifier = Modifier.height(8.dp))
            }

            if (canDelete) {
                Button(
                    onClick = {
                        FirebaseFirestore.getInstance()
                            .collection("campsites")
                            .document(campsiteId)
                            .delete()
                            .addOnSuccessListener { navController.popBackStack() }
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = Color.Red),
                    shape = RectangleShape,
                    modifier = Modifier.fillMaxWidth().testTag("deleteCampsiteButton"),
                ) {
                    Text("Delete Campsite", color = Color.White)
                }
                Spacer(modifier = Modifier.height(8.dp))
            }

            if (campsite != null) {
                Button(
                    onClick = { navController.navigate("campsiteReviews/$campsiteId") },
                    shape = RectangleShape,
                    modifier = Modifier
                        .fillMaxWidth()
                        .testTag("toReviewsButton"),
                ) {
                    Text("Reviews")
                }

                Spacer(modifier = Modifier.height(8.dp))
            }

            if (canRate) {
                Button(
                    onClick = { showRateDialog = true },
                    enabled = !isSubmittingRating,
                    shape = RectangleShape,
                    modifier = Modifier
                        .fillMaxWidth()
                        .testTag("rateCampsiteButton"),
                ) {
                    Text(
                        when {
                            isSubmittingRating -> "Saving rating..."
                            myRating != null -> "Change My Rating ($myRating ★)"
                            else -> "Rate Campsite"
                        }
                    )
                }

                Spacer(modifier = Modifier.height(8.dp))
            }

            if (!isOwnerOfSite && campsite != null && campsite!!.ownerId.isNotBlank()) {
                Button(
                    onClick = { showMessageOwnerDialog = true },
                    shape = RectangleShape,
                    modifier = Modifier
                        .fillMaxWidth()
                        .testTag("messageOwnerButton"),
                ) {
                    Text("Message Owner")
                }
                Spacer(modifier = Modifier.height(8.dp))
            }

            // Join or leave this campsite's active lottery (US 1.6).
            LotteryJoinSection(
                lotteries = openWaitlists,
                userId = deviceId,
                campsiteOwnerId = campsite?.ownerId,
                repository = lotteryJoinRepository,
                loadError = waitlistsError,
            )
        }
    }
}

